interface.definition:
#"SYSTEM_SYSRULES_gridField_v1"(
  label: "Rotational ASKs",
  labelPosition: "COLLAPSED",
  emptyGridMessage: "No Rotational ASK Records Found",
  data: ri!rotationalAsks,
  refreshAlways: true,
  columns: {
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Rotational Request",
      sortField: "askId",
      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
          text:if(and(
            todate(fv!row.createdOn)<todate(#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045"),
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(fv!row.askName)),
            fv!row.region &  " - " & "FY"&right(fv!row.fyear,2),
            fv!row.askName),

          link: #"SYSTEM_SYSRULES_recordLink"(
            recordType: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3340173",
            identifier: fv!row.rotationalAskId
          )
        )
      )
    ),    
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Version",
      sortField: "version",
      align: "CENTER",
      value: fv!row.version
    ),
    /*Modified by Bhavana | APAP-10382*/
    /*a!gridColumn(*/
      /*label: "Region",*/
      /*sortField: "region",*/
      /*align: "CENTER",*/
      /*value: fv!row.region*/
    /*),*/
    /*Modified by Safia | APAP-10630*/
    /*a!gridColumn(*/
      /*label: "Year",*/
      /*sortField: "fYear",*/
      /*align: "CENTER",*/
      /*value: fv!row.fYear*/
    /*),*/
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Type",
      sortField: "askType",
      align: "CENTER",
      value: fv!row.askType
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Created By",
      align: "CENTER",
      sortField: "createdBy",
      value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(user: fv!row.createdBy)
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Created On",
      align: "CENTER",
      sortField: "createdOn",
      value: fv!row.createdOn
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Status",
      align: "CENTER",
      sortField: "isCompleted",
      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextIcon"(
          icon: if(
            fv!row.isCompleted,
            "check-circle-o",
            fv!row.statusId = #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
            "times-circle-o",
            "play-circle-o"
          ),
          size: "MEDIUM",
          color: if(
            fv!row.isCompleted,
            "POSITIVE",
            fv!row.statusId = #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
            "NEGATIVE",
            "#F1CE0B"
          ),
          caption: if(
            fv!row.isCompleted,
            "Completed",
            fv!row.statusId = #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
            "Cancelled",
            "In Progress"
          )
        )
        /*value:a!richTextIcon(*/
          /*icon: if(fv!row.isCompleted,"check-circle-o","play-circle-o"),*/
          /*size: "MEDIUM",*/
          /*color: if(fv!row.isCompleted,"POSITIVE","#F1CE0B"),*/
          /*caption: if(fv!row.isCompleted,"Completed","In Progess")*/
        /*)*/
      )
    )
  },
  selectionValue: ri!selectedRotationalTaskIds,
  selectionSaveInto: ri!selectedRotationalTaskIds,
  rowHeader: 1,
  spacing: "DENSE",
  borderStyle: "LIGHT",
  shadeAlternateRows: true()
)
